import {TextSelection, NodeSelection, Selection} from "prosemirror-state"
import {ResolvedPos} from "prosemirror-model"

import * as browser from "./browser"
import {isEquivalentPosition, domIndex, isOnEdge, selectionCollapsed, isElt, isText,
        contains, DOMNode, DOMSelectionRange, DOMSelection, deepActiveElement, writeSelection} from "./dom"
import {EditorView} from "./index"
import {ViewDesc, NodeViewDesc, CustomNodeViewDesc} from "./viewdesc"

class StoredDOMSel implements DOMSelectionRange {
  constructor(readonly anchorNode: Node | null,
              readonly anchorOffset: number,
              readonly focusNode: Node | null,
              readonly focusOffset: number) {}

  static from(range: DOMSelectionRange) {
    if (range instanceof StoredDOMSel) return range
    return new StoredDOMSel(range.anchorNode, range.anchorOffset, range.focusNode, range.focusOffset)
  }

  static null = new StoredDOMSel(null, 0, null, 0)

  eq(sel: DOMSelectionRange) {
    return sel.anchorNode == this.anchorNode && sel.anchorOffset == this.anchorOffset &&
      sel.focusNode == this.focusNode && sel.focusOffset == this.focusOffset
  }
}

// Tracks the relation between the DOM selection and the editor state
// selection. Caches the current selection range for cheap access.
//
// Will read the DOM selection state on selectionchange events and
// when explicitly synced. Not guaranteed to hold the _current_ DOM
// selection unless you are on a code path where you know it was
// synced. So for one-off event handlers, it's safer to use
// `domSel.readRange()` (fetches the range from the DOM), whereas in
// things like the DOM flush logic, `domSel.range` is safe and cheap
// to use.
export class DOMSelState {
  // The last read selection range. Updated by `read`, `sync`,
  // `ignore`, and `clear`. Only means anything when `active` is true.
  range = StoredDOMSel.null
  // Indicates whether the editor has focus and selection
  active = false
  // True when we are active and the current range has been synced
  // with the state selection
  synced = false
  suppress = false
  currentDocument: Document | null = null

  constructor(readonly view: EditorView) {
    this.onSelectionChange = this.onSelectionChange.bind(this)
  }

  ensureListener() {
    let doc = this.view.dom.ownerDocument
    if (doc != this.currentDocument) {
      if (this.currentDocument) this.currentDocument.removeEventListener("selectionchange", this.onSelectionChange)
      this.currentDocument = doc
      doc.addEventListener("selectionchange", this.onSelectionChange)
    }
  }

  destroy() {
    if (this.currentDocument) {
      this.currentDocument.removeEventListener("selectionchange", this.onSelectionChange)
      this.currentDocument = null
    }
    this.active = false
    this.range = StoredDOMSel.null
  }

  suppressChanges() {
    this.suppress = true
    setTimeout(() => this.suppress = false, 50)
  }

  onSelectionChange() {
    if (this.suppress && this.view.hasFocus()) return this.sync()
    if (this.read()) this.view.domObserver.flush(false)
  }

  // Reads the active range from the DOM, if any.
  readRange(): StoredDOMSel {
    let {view} = this
    let sel: DOMSelection | null | false = view.dom.isConnected !== false && view.domSelection()
    if (!sel) return StoredDOMSel.null
    if (browser.safari && view.root.nodeType === 11 && deepActiveElement(view.dom.ownerDocument) == view.dom)
      return StoredDOMSel.from(safariShadowSelectionRange(view, sel) || sel)
    return StoredDOMSel.from(sel)
  }

  read() {
    this.ensureListener()
    let sel = hasFocusAndSelection(this.view)
    if (!sel) {
      this.active = false
      this.range = StoredDOMSel.null
      return
    }
    this.active = true
    if (this.range.eq(sel)) return false
    this.range = sel
    this.synced = false
    return true
  }

  // Sync the DOM selection to the state selection
  sync(force = false) {
    let {view} = this
    if (!view.docView) return
    this.ensureListener()
    view.domObserver.stopped(() => {
      syncNodeSelection(view, view.state.selection)

      let sel = view.state.selection
      if (editorOwnsSelection(view)) {
        let {desc, start} = innerViewDesc(view.docView, sel.from, sel.to, 0)
        if (view.cursorWrapper) {
          selectCursorWrapper(view)
        } else if (desc instanceof CustomNodeViewDesc && desc.spec.setSelection) {
          desc.spec.setSelection(sel.anchor - start, sel.head - start, view.root)
        } else {
          selectionToDOM(view, force, desc, start)
        }
        this.synced = this.active = true
      }

      if (sel.visible == view.dom.classList.contains("ProseMirror-hideselection")) {
        if (sel.visible) {
          view.dom.classList.remove("ProseMirror-hideselection")
        } else {
          view.dom.classList.add("ProseMirror-hideselection")
          removeClassOnSelectionChange(view)
        }
      }

      this.range = this.readRange()
    })
  }

  ignore(sel: DOMSelectionRange = this.readRange()) {
    this.range = StoredDOMSel.from(sel)
    this.synced = true
  }

  // Called when the editor is blurred
  deactivate() {
    this.range = StoredDOMSel.null
    this.active = this.synced = false
  }
}

// Used to work around the fact that is is rather hard to get the
// selection in a shadow root in Safari.
function safariShadowSelectionRange(view: EditorView, selection: DOMSelection): DOMSelectionRange | null {
  if ((selection as any).getComposedRanges) {
    let range = (selection as any).getComposedRanges(view.root)[0] as StaticRange
    if (range) return rangeToSelectionRange(view, range)
  }

  let found: StaticRange | undefined
  function read(event: InputEvent) {
    event.preventDefault()
    event.stopImmediatePropagation()
    found = event.getTargetRanges()[0]
  }

  // Because Safari (at least in 2018-2022) doesn't provide regular
  // access to the selection inside a shadowRoot, we have to perform a
  // ridiculous hack to get at it—using `execCommand` to trigger a
  // `beforeInput` event so that we can read the target range from the
  // event.
  view.dom.addEventListener("beforeinput", read, true)
  document.execCommand("indent")
  view.dom.removeEventListener("beforeinput", read, true)

  return found ? rangeToSelectionRange(view, found) : null
}

function rangeToSelectionRange(view: EditorView, range: StaticRange) {
  let anchorNode = range.startContainer, anchorOffset = range.startOffset
  let focusNode = range.endContainer, focusOffset = range.endOffset

  let currentAnchor = view.domAtPos(view.state.selection.anchor)
  // Since such a range doesn't distinguish between anchor and head,
  // use a heuristic that flips it around if its end matches the
  // current anchor.
  if (isEquivalentPosition(currentAnchor.node, currentAnchor.offset, focusNode, focusOffset))
    [anchorNode, anchorOffset, focusNode, focusOffset] = [focusNode, focusOffset, anchorNode, anchorOffset]
  return new StoredDOMSel(anchorNode, anchorOffset, focusNode, focusOffset)
}

export function selectionFromDOM(view: EditorView, domSel: DOMSelectionRange, origin: string | null = null) {
  let doc = view.state.doc
  if (!domSel.focusNode) return null
  let nearestDesc = view.docView.nearestDesc(domSel.focusNode), inWidget = nearestDesc && nearestDesc.size == 0
  let head = view.docView.posFromDOM(domSel.focusNode, domSel.focusOffset, 1)
  if (head < 0) return null
  let $head = doc.resolve(head), anchor, selection
  if (selectionCollapsed(domSel)) {
    anchor = head
    while (nearestDesc && !nearestDesc.node) nearestDesc = nearestDesc.parent
    if (nearestDesc && nearestDesc.node!.isAtom && NodeSelection.isSelectable(nearestDesc.node!) &&
        nearestDesc.parent &&
        !(nearestDesc.node!.isInline && isOnEdge(domSel.focusNode, domSel.focusOffset, nearestDesc.dom))) {
      let pos = nearestDesc.posBefore
      selection = new NodeSelection(head == pos ? $head : doc.resolve(pos))
    } else if (browser.gecko && origin == "key" && head > view.state.selection.to &&
               isElt(domSel.focusNode) && domSel.focusOffset == domSel.focusNode.childNodes.length &&
               nearestDesc && nearestDesc.posAtStart > view.state.selection.to) {
      // Firefox will jump across scrollable wrapper nodes on keyboard
      // cursor motion (#1594). This tries to detect this situation
      // and work around it.
      for (let scan = domSel.focusNode;; scan = scan.parentNode) {
        if (getComputedStyle(scan).overflow != "visible") {
          selection = Selection.findFrom(doc.resolve(nearestDesc.posAtStart), 1)
          break
        }
        if (scan == nearestDesc.dom || scan.nextSibling || !scan.parentNode || !isElt(scan.parentNode)) break
      }
    }

  } else {
    if (domSel instanceof view.dom.ownerDocument.defaultView!.Selection && domSel.rangeCount > 1) {
      let min = head, max = head
      for (let i = 0; i < domSel.rangeCount; i++) {
        let range = domSel.getRangeAt(i)
        min = Math.min(min, view.docView.posFromDOM(range.startContainer, range.startOffset, 1))
        max = Math.max(max, view.docView.posFromDOM(range.endContainer, range.endOffset, -1))
      }
      if (min < 0) return null
      ;[anchor, head] = max == view.state.selection.anchor ? [max, min] : [min, max]
      $head = doc.resolve(head)
    } else {
      anchor = view.docView.posFromDOM(domSel.anchorNode!, domSel.anchorOffset, 1)
    }
    if (anchor < 0) return null
  }
  let $anchor = doc.resolve(anchor)

  if (!selection) {
    let bias = origin == "pointer" || (view.state.selection.head < $head.pos && !inWidget) ? 1 : -1
    selection = selectionBetween(view, $anchor, $head, bias)
  }
  return selection
}

function editorOwnsSelection(view: EditorView) {
  return view.editable ? view.hasFocus() :
    hasSelection(view, view.domSel.readRange()) && (!document.activeElement || document.activeElement.contains(view.dom))
}

function selectionToDOM(view: EditorView, force: boolean, desc: ViewDesc, start: number) {
  let sel = view.state.selection
  let {anchor, head} = sel, resetEditableFrom, resetEditableTo
  if (brokenSelectBetweenUneditable && !(sel instanceof TextSelection)) {
    if (!sel.$from.parent.inlineContent)
      resetEditableFrom = temporarilyEditableNear(view, sel.from)
    if (!sel.empty && !sel.$from.parent.inlineContent)
      resetEditableTo = temporarilyEditableNear(view, sel.to)
  }

  let anchorDOM = desc.domFromPos(anchor - start, anchor > start ? -1 : 1)
  let headDOM = head == anchor ? anchorDOM : desc.domFromPos(head - start, head > start ? -1 : 1)
  setSelection(anchor, head, anchorDOM, headDOM, view, force)

  if (brokenSelectBetweenUneditable) {
    if (resetEditableFrom) resetEditable(resetEditableFrom)
    if (resetEditableTo) resetEditable(resetEditableTo)
  }
}

// See if the selection falls within a custom node view that overrides it
function innerViewDesc(desc: ViewDesc, from: number, to: number, start = 0): {desc: ViewDesc, start: number} {
  for (let i = 0, off = start; i < desc.children.length; i++) {
    let child = desc.children[i], end = off + child.size
    if (from > off && to < end) return innerViewDesc(child, from, to, off + child.border)
    off = end
  }
  return {desc, start}
}

function setSelection(
  anchor: number, head: number,
  anchorDOM: {node: Node, offset: number}, headDOM: {node: Node, offset: number},
  view: EditorView, force: boolean
) {
  let brKludge = false
  // On Firefox, using Selection.collapse to put the cursor after a
  // BR node for some reason doesn't always work (#1073). On Safari,
  // the cursor sometimes inexplicable visually lags behind its
  // reported position in such situations (#1092).
  if ((browser.gecko || browser.safari) && anchor == head) {
    let {node, offset} = anchorDOM
    if (isText(node)) {
      brKludge = !!(offset && node.nodeValue![offset - 1] == "\n")
      // Issue #1128
      if (brKludge && offset == node.nodeValue!.length) {
        for (let scan: DOMNode | null = node, after; scan; scan = scan.parentNode) {
          if (after = scan.nextSibling) {
            if (after.nodeName == "BR")
              anchorDOM = headDOM = {node: after.parentNode!, offset: domIndex(after) + 1}
            break
          }
          let desc = scan.pmViewDesc
          if (desc && desc.node && desc.node.isBlock) break
        }
      }
    } else {
      let prev = node.childNodes[offset - 1]
      brKludge = prev && (prev.nodeName == "BR" || (prev as HTMLElement).contentEditable == "false")
    }
  }

  let selRange = view.domSel.readRange()
  // Firefox can act strangely when the selection is in front of an
  // uneditable node. See #1163 and https://bugzilla.mozilla.org/show_bug.cgi?id=1709536
  if (browser.gecko && selRange.focusNode && selRange.focusNode != headDOM.node && isElt(selRange.focusNode)) {
    let after = selRange.focusNode.childNodes[selRange.focusOffset]
    if (after && (after as HTMLElement).contentEditable == "false") force = true
  }

  if (!(force || brKludge && browser.safari) &&
      isEquivalentPosition(anchorDOM.node, anchorDOM.offset, selRange.anchorNode!, selRange.anchorOffset) &&
      isEquivalentPosition(headDOM.node, headDOM.offset, selRange.focusNode!, selRange.focusOffset))
    return

  writeSelection(view.domSelection()!, {
    focusNode: headDOM.node, focusOffset: headDOM.offset,
    anchorNode: anchorDOM.node, anchorOffset: anchorDOM.offset
  })
}

// Kludge to work around Webkit not allowing a selection to start/end
// between non-editable block nodes. We briefly make something
// editable, set the selection, then set it uneditable again.

const brokenSelectBetweenUneditable = browser.safari || browser.chrome && browser.chrome_version < 63

function temporarilyEditableNear(view: EditorView, pos: number) {
  let {node, offset} = view.docView.domFromPos(pos, 0)
  let after = offset < node.childNodes.length ? node.childNodes[offset] : null
  let before = offset ? node.childNodes[offset - 1] : null
  if (browser.safari && after && (after as HTMLElement).contentEditable == "false") return setEditable(after as HTMLElement)
  if ((!after || (after as HTMLElement).contentEditable == "false") &&
      (!before || (before as HTMLElement).contentEditable == "false")) {
    if (after) return setEditable(after as HTMLElement)
    else if (before) return setEditable(before as HTMLElement)
  }
}

function setEditable(element: HTMLElement) {
  element.contentEditable = "true"
  if (browser.safari && element.draggable) { element.draggable = false; (element as any).wasDraggable = true }
  return element
}

function resetEditable(element: HTMLElement) {
  element.contentEditable = "false"
  if ((element as any).wasDraggable) { element.draggable = true; (element as any).wasDraggable = null }
}

function removeClassOnSelectionChange(view: EditorView) {
  let doc = view.dom.ownerDocument
  doc.removeEventListener("selectionchange", view.input.hideSelectionGuard!)
  let domSel = view.domSel.readRange()
  let node = domSel.anchorNode, offset = domSel.anchorOffset
  doc.addEventListener("selectionchange", view.input.hideSelectionGuard = () => {
    if (domSel.anchorNode != node || domSel.anchorOffset != offset) {
      doc.removeEventListener("selectionchange", view.input.hideSelectionGuard!)
      setTimeout(() => {
        if (!editorOwnsSelection(view) || view.state.selection.visible)
          view.dom.classList.remove("ProseMirror-hideselection")
      }, 20)
    }
  })
}

function selectCursorWrapper(view: EditorView) {
  let domSel = view.domSelection()
  if (!domSel) return
  let node = view.cursorWrapper!.dom, img = node.nodeName == "IMG"
  if (img) domSel.collapse(node.parentNode!, domIndex(node) + 1)
  else domSel.collapse(node, 0)
}

export function syncNodeSelection(view: EditorView, sel: Selection) {
  if (sel instanceof NodeSelection) {
    let desc = view.docView.descAt(sel.from)
    if (desc != view.lastSelectedViewDesc) {
      clearNodeSelection(view)
      if (desc) (desc as NodeViewDesc).selectNode()
      view.lastSelectedViewDesc = desc
    }
  } else {
    clearNodeSelection(view)
  }
}

// Clear all DOM statefulness of the last node selection.
function clearNodeSelection(view: EditorView) {
  if (view.lastSelectedViewDesc) {
    if (view.lastSelectedViewDesc.parent)
      (view.lastSelectedViewDesc as NodeViewDesc).deselectNode()
    view.lastSelectedViewDesc = undefined
  }
}

export function selectionBetween(view: EditorView, $anchor: ResolvedPos, $head: ResolvedPos, bias?: number) {
  let sel = view.someProp("createSelectionBetween", f => f(view, $anchor, $head))
    || TextSelection.between($anchor, $head, bias)
  view.someProp("adjustSelectionFromDOM", f => { sel = f(view, sel) })
  return sel
}

export function hasFocusAndSelection(view: EditorView) {
  if (view.editable && !view.hasFocus()) return null
  let sel = view.domSel.readRange()
  return sel && hasSelection(view, sel) ? sel : null
}

export function hasSelection(view: EditorView, sel: DOMSelectionRange) {
  if (!sel.anchorNode) return false
  try {
    // Firefox will raise 'permission denied' errors when accessing
    // properties of `sel.anchorNode` when it's in a generated CSS
    // element.
    return contains(view.dom, sel.anchorNode) && (view.editable || contains(view.dom, sel.focusNode))
  } catch(_) {
    return false
  }
}
